// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 마이페이지 (17번)" (cf5111d9c66847948c10482de8b4ad14).
// #30: 프로필 카드·활동 현황·최근 채택 내역, #31: 등급·뱃지 카드, #32: 내 질문·답변 목록을 API와 연결했다.
// #190: docs/ui-guide.md 공통 값(uiStyles, StatusBadge, SortTabs, GradeIcon, BadgeIcon, writer)으로 바꿨다.
import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { getErrorMessage } from "../api/client";
import {
  getAcceptedAnswers,
  getMyAnswers,
  getMyCategories,
  getMyGrade,
  getMyInfo,
  getMyQuestions,
  type AcceptedAnswer,
  type MyAnswer,
  type MyQuestion,
  type Page,
  type Badge,
  type GradeInfo,
  type MyInfo,
} from "../api/mypage";
import { getCategories } from "../api/tag";
import BadgeIcon from "../components/BadgeIcon";
import Footer from "../components/Footer";
import { GRADES } from "../components/gradeBadge";
import GradeIcon from "../components/GradeIcon";
import Header from "../components/Header";
import ListStatus from "../components/ListStatus";
import Pagination from "../components/Pagination";
import ProfileDetails from "../components/ProfileDetails";
import { detailPath } from "../components/questionList";
import SortTabs from "../components/SortTabs";
import StatusBadge from "../components/StatusBadge";
import { BUTTON, buttonClass, CARD, CATEGORY, FOCUS, NOTICE, PAGE_BACKGROUND } from "../components/uiStyles";
import { formatDate, formatNumber, formatPercent } from "../components/writer";
import { useAuth } from "../hooks/useAuth";
import "./Mypage.css";

const RECENT_ACCEPTED_SIZE = 5;
const BADGE_PREVIEW_SIZE = 3;
const PAGE_SIZE = 10;

// 큰 카드는 24px, 휴대폰 폭에서는 16px (ui-guide.md 2절)
const CARD_PADDING = "p-4 sm:p-6";
// 카드 안 제목 줄: 아이콘 + 섹션 제목, 아래 연한 구분선
const SECTION_HEAD = "flex flex-wrap items-center justify-between gap-2 pb-3 mb-4 border-b-2 border-devin-line";
const SECTION_TITLE = "flex items-center gap-1.5 text-lg font-extrabold text-devin-ink";

interface MypageData {
  me: MyInfo;
  grade: GradeInfo;
  categoryNames: string[];
  questionCount: number;
  answerCount: number;
  acceptedCount: number;
  recentAccepted: AcceptedAnswer[];
}

// 요약 카드에는 획득한 뱃지를 먼저, 남는 자리에 다음으로 노릴 미획득 뱃지를 보여준다.
function previewBadges(badges: Badge[]) {
  return [...badges.filter((b) => b.acquired), ...badges.filter((b) => !b.acquired)].slice(0, BADGE_PREVIEW_SIZE);
}

// 활동 수는 목록 API의 totalElements를 쓴다 (size=1로 개수만 받는다).
async function loadMypage(): Promise<MypageData> {
  const [me, grade, setting, categories, questions, answers, accepted] = await Promise.all([
    getMyInfo(),
    getMyGrade(),
    getMyCategories(),
    getCategories(),
    getMyQuestions(0, 1),
    getMyAnswers(0, 1),
    getAcceptedAnswers(0, RECENT_ACCEPTED_SIZE),
  ]);
  return {
    me,
    grade,
    // 카테고리 목록 순서대로 관심 카테고리 이름을 보여준다
    categoryNames: categories.filter((c) => setting.categoryIds.includes(c.categoryId)).map((c) => c.name),
    questionCount: questions.totalElements,
    answerCount: answers.totalElements,
    acceptedCount: accepted.totalElements,
    recentAccepted: accepted.content,
  };
}

function Icon({ name }: { name: string }) {
  return (
    <span className="material-symbols-outlined text-[20px] leading-none shrink-0" aria-hidden="true">
      {name}
    </span>
  );
}

type ActivityTab = "questions" | "answers";

// 질문: 채택 / 미채택(답변은 있지만 채택 전) / 답변 대기(답변 0개). 답변: 채택됨 / 미채택
function ItemStatus({ item }: { item: MyQuestion | MyAnswer }) {
  if ("answerId" in item) return <StatusBadge kind={item.accepted ? "answerAccepted" : "unaccepted"} />;
  if (item.accepted) return <StatusBadge kind="accepted" />;
  return <StatusBadge kind={item.answerCount === 0 ? "waiting" : "unaccepted"} />;
}

// 내 질문·답변 목록 (REQ-MYPAGE-008, #32): 탭, 최신순, 페이징, 클릭 시 질문 상세로 이동.
// 수정·삭제는 질문 상세에서만 한다 (REQ-QUESTION-006·007).
function MyActivityList({ questionCount, answerCount }: { questionCount?: number; answerCount?: number }) {
  const [tab, setTab] = useState<ActivityTab>("questions");
  const [page, setPage] = useState(0);
  const [result, setResult] = useState<{ tab: ActivityTab; data: Page<MyQuestion> | Page<MyAnswer> } | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setError(null);
    const request = tab === "questions" ? getMyQuestions(page, PAGE_SIZE) : getMyAnswers(page, PAGE_SIZE);
    request
      .then((data) => {
        if (!cancelled) setResult({ tab, data });
      })
      .catch((err) => {
        if (!cancelled) setError(getErrorMessage(err, "목록을 불러오지 못했어요. 잠시 후 다시 시도해 주세요."));
      });
    return () => {
      cancelled = true;
    };
  }, [tab, page]);

  const changeTab = (next: ActivityTab) => {
    if (next === tab) return;
    setTab(next);
    setPage(0);
  };

  // 탭을 바꾼 직후에는 이전 탭 결과를 보여주지 않는다.
  const data = result?.tab === tab ? result.data : null;

  return (
    <section className="space-y-3" data-purpose="user-history-list">
      <SortTabs
        tabs={[
          { value: "questions", label: "내 질문", count: questionCount },
          { value: "answers", label: "내 답변", count: answerCount },
        ]}
        value={tab}
        onChange={changeTab}
        label="내 활동"
      />

      <div className={`${CARD} ${CARD_PADDING}`}>
        <p
          className="pb-3 mb-4 border-b-2 border-devin-line text-xs font-semibold text-devin-gray"
          data-field="listSummary"
        >
          {`작성한 ${tab === "questions" ? "질문" : "답변"} `}
          <span className="font-bold text-devin-ink tabular-nums">
            {data ? formatNumber(data.totalElements) : "-"}개
          </span>
          {" · 최신순"}
        </p>

        {error && <ListStatus kind="error">{error}</ListStatus>}
        {!data && !error && <ListStatus kind="loading">불러오는 중이에요.</ListStatus>}
        {data && data.content.length === 0 && (
          <ListStatus
            kind="empty"
            action={
              tab === "questions" ? (
                <Link className={buttonClass("primary", "sm")} to="/ask">
                  질문하기
                </Link>
              ) : (
                <Link className={buttonClass("secondary", "sm")} to="/questions">
                  질문 둘러보기
                </Link>
              )
            }
          >
            {tab === "questions" ? "아직 작성한 질문이 없어요. 첫 질문을 남겨 보세요." : "아직 작성한 답변이 없어요."}
          </ListStatus>
        )}

        {data && data.content.length > 0 && (
          <ul className="space-y-3" data-purpose="history-items">
            {data.content.map((item) => {
              const answer = "answerId" in item ? item : null;
              return (
                <li key={answer ? `a${answer.answerId}` : `q${item.questionId}`}>
                  <Link
                    className={`block p-4 rounded-xl border-devin border-devin-ink bg-devin-paper hover:bg-devin-bg transition-colors group ${FOCUS}`}
                    data-item={answer ? `answer-${answer.answerId}` : `question-${item.questionId}`}
                    to={detailPath(item.questionId)}
                  >
                    <div className="flex flex-wrap items-center gap-2" data-field="itemStatus">
                      <ItemStatus item={item} />
                      <h3
                        className="min-w-0 text-base font-extrabold text-devin-ink break-all group-hover:underline"
                        data-field="itemTitle"
                      >
                        {item.title}
                      </h3>
                    </div>
                    <p className="mt-2 flex flex-wrap items-center gap-x-2 text-xs text-devin-gray tabular-nums">
                      <span>{formatDate(item.createdAt)}</span>
                      {!answer && (
                        <>
                          <span aria-hidden="true">·</span>
                          <span data-field="itemAnswerCount">
                            답변 {formatNumber((item as MyQuestion).answerCount)}
                          </span>
                        </>
                      )}
                      <span aria-hidden="true">·</span>
                      <span data-field="itemLikes">좋아요 {formatNumber(item.likeCount)}</span>
                    </p>
                  </Link>
                </li>
              );
            })}
          </ul>
        )}

        {/* 공통 페이지 번호 (page는 1부터 센다. 한 페이지뿐이면 표시하지 않는다) */}
        {data && <Pagination page={page + 1} totalPages={data.totalPages} onChange={(next) => setPage(next - 1)} />}
      </div>
    </section>
  );
}

function StatRow({ label, field, value }: { label: string; field: string; value?: number }) {
  return (
    <div className="flex items-center justify-between py-2.5 border-b border-devin-line">
      <dt className="font-bold text-devin-gray">{label}</dt>
      <dd className="text-base font-black text-devin-ink tabular-nums" data-field={field}>
        {value === undefined ? "-" : formatNumber(value)}
        <span className="ml-0.5 text-xs font-medium text-devin-gray">개</span>
      </dd>
    </div>
  );
}

export default function Mypage() {
  const navigate = useNavigate();
  const { user, initializing } = useAuth();
  const [data, setData] = useState<MypageData | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);

  // 로그인이 필요한 화면이다. 새로고침 직후에는 reissue로 로그인 상태를 복구할 때까지 기다린다.
  useEffect(() => {
    if (!initializing && !user) {
      navigate("/login", { replace: true });
    }
  }, [initializing, user, navigate]);

  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    loadMypage()
      .then((result) => {
        if (!cancelled) setData(result);
      })
      .catch((error) => {
        if (!cancelled) {
          setLoadError(getErrorMessage(error, "마이페이지 정보를 불러오지 못했어요. 잠시 후 다시 시도해 주세요."));
        }
      });
    return () => {
      cancelled = true;
    };
  }, [user]);

  const acquiredCount = data ? data.grade.badges.filter((b) => b.acquired).length : 0;
  const acceptRate = data?.me.acceptRate ?? 0;

  return (
    <div id="page-mypage">
      <div className={`${PAGE_BACKGROUND} text-devin-ink min-h-screen flex flex-col antialiased`}>
        <Header />
        <main className="flex-1 max-w-6xl w-full mx-auto px-4 sm:px-6 py-6 space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-stretch">
            {/* 내 프로필 (REQ-MYPAGE-001, 004) */}
            <section className={`lg:col-span-5 ${CARD} ${CARD_PADDING}`} data-purpose="user-profile-card">
              <div className={SECTION_HEAD}>
                <h1 className="text-2xl font-black text-devin-ink">내 프로필</h1>
                <div className="flex items-center gap-2">
                  <Link className={buttonClass("secondary", "sm")} to="/profile-edit">
                    프로필 수정
                  </Link>
                  <Link className={buttonClass("secondary", "sm")} to="/account-edit">
                    개인정보 수정
                  </Link>
                </div>
              </div>

              {loadError && (
                <p className={NOTICE.error} role="alert">
                  <Icon name="error" />
                  {loadError}
                </p>
              )}
              {!data && !loadError && <ListStatus kind="loading">불러오는 중이에요.</ListStatus>}
              {data && (
                <>
                  <ProfileDetails profile={data.me} />
                  {/* 관심 카테고리 (수정은 프로필 수정 화면) */}
                  <div className="flex items-start pt-3 text-sm">
                    <span className="w-24 font-bold text-devin-gray shrink-0">관심 카테고리</span>
                    <span className="flex flex-wrap gap-x-3 gap-y-1.5" data-field="categories">
                      {data.categoryNames.length === 0 ? (
                        <span className="text-devin-gray-light">미등록</span>
                      ) : (
                        data.categoryNames.map((name) => (
                          <span className={CATEGORY} key={name}>
                            {name}
                          </span>
                        ))
                      )}
                    </span>
                  </div>
                </>
              )}
            </section>

            {/* 등급·뱃지 + 활동 현황 */}
            <div
              className={`lg:col-span-7 ${CARD} grid grid-cols-1 sm:grid-cols-12 divide-y-2 sm:divide-y-0 sm:divide-x-2 divide-devin-line`}
            >
              {/* 등급 및 뱃지 (REQ-MYPAGE-005, #31) */}
              <section
                className={`sm:col-span-7 ${CARD_PADDING} flex flex-col justify-between gap-6`}
                data-purpose="user-tier-badges"
              >
                <div>
                  <div className={SECTION_HEAD}>
                    <h2 className={SECTION_TITLE}>
                      <Icon name="emoji_events" />
                      등급 및 뱃지
                    </h2>
                    {/* 밑줄은 글자에만 긋는다. 아이콘까지 그으면 아이콘 글꼴의 기준선이 달라 밑줄이 끊겨 보인다.
                        아이콘은 폭을 고정해 글꼴을 불러오기 전에 이름(arrow_forward)이 글자로 늘어지지 않게 한다. */}
                    <Link className={`${BUTTON.text} no-underline`} to="/grades-badges">
                      <span className="underline underline-offset-[3px]">전체 보기</span>
                      <span
                        className="material-symbols-outlined inline-block w-[18px] overflow-hidden text-[18px] leading-none"
                        aria-hidden="true"
                      >
                        arrow_forward
                      </span>
                    </Link>
                  </div>

                  <div className="space-y-3">
                    <div className="flex items-center gap-2 text-sm">
                      <span className="font-bold text-devin-gray">현재 등급</span>
                      <span data-field="grade">{data ? <GradeIcon grade={data.grade.grade} withLabel /> : "-"}</span>
                    </div>

                    {/* 다음 등급까지 남은 조건 */}
                    {data && (
                      <p className={NOTICE.info} data-field="nextGrade">
                        <Icon name="info" />
                        <span>
                          {data.grade.nextGrade && data.grade.nextGradeMin !== null
                            ? `다음 등급(${GRADES[data.grade.nextGrade].label})까지 채택 ${formatNumber(
                                data.grade.nextGradeMin - data.grade.acceptedCount,
                              )}회 남았어요.`
                            : "최고 등급이에요."}
                        </span>
                      </p>
                    )}
                  </div>
                </div>

                {/* 획득한 뱃지 먼저, 남는 자리는 아직 얻지 못한 뱃지 */}
                <div>
                  <span className="block mb-2 text-xs font-bold text-devin-gray tabular-nums">
                    획득 뱃지{data && ` ${acquiredCount}/${data.grade.badges.length}`}
                  </span>
                  <div className="flex items-start gap-4 sm:gap-6" data-purpose="badge-preview">
                    {data &&
                      previewBadges(data.grade.badges).map((badge) => (
                        <Link
                          className={`flex flex-col items-center gap-1.5 rounded-lg ${FOCUS}`}
                          data-acquired={badge.acquired}
                          key={badge.code}
                          title={badge.acquired ? badge.condition : `${badge.condition} 달성 시 획득`}
                          to="/grades-badges"
                        >
                          <BadgeIcon code={badge.code} acquired={badge.acquired} />
                          <span
                            className={`text-xs font-bold ${badge.acquired ? "text-devin-ink" : "text-devin-gray-light"}`}
                          >
                            {badge.name}
                          </span>
                        </Link>
                      ))}
                  </div>
                </div>
              </section>

              {/* 나의 활동 현황 (REQ-MYPAGE-006) */}
              <section
                className={`sm:col-span-5 ${CARD_PADDING} flex flex-col justify-between`}
                data-purpose="user-activity-stats"
              >
                <div>
                  <div className={SECTION_HEAD}>
                    <h2 className={SECTION_TITLE}>
                      <Icon name="bar_chart" />
                      나의 활동 현황
                    </h2>
                  </div>
                  <dl className="text-sm" data-purpose="activity-counts">
                    <StatRow label="작성 질문" field="questionCount" value={data?.questionCount} />
                    <StatRow label="작성 답변" field="answerCount" value={data?.answerCount} />
                    <StatRow label="채택된 답변" field="acceptedCount" value={data?.acceptedCount} />
                  </dl>
                </div>

                {/* 채택률 막대 (채택된 답변 수 ÷ 전체 답변 수) */}
                <div className="mt-4">
                  <div className="mb-1.5 flex items-baseline justify-between">
                    <span className="text-sm font-bold text-devin-gray">채택률</span>
                    <span className="text-lg font-black text-devin-ink tabular-nums" data-field="acceptRate">
                      {data ? formatPercent(acceptRate) : "-"}
                    </span>
                  </div>
                  <div
                    className="w-full h-3 rounded-full bg-devin-tag border-[1.5px] border-devin-ink overflow-hidden"
                    role="progressbar"
                    aria-label="채택률"
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-valuenow={acceptRate}
                  >
                    <div
                      className="bg-devin-blue h-full transition-all"
                      style={{ width: `${Math.min(100, acceptRate)}%` }}
                    />
                  </div>
                </div>
              </section>
            </div>
          </div>

          {/* 최근 채택 내역 (REQ-MYPAGE-007, 최신순) */}
          <section className={`${CARD} ${CARD_PADDING}`} data-purpose="recent-accepted">
            <div className={SECTION_HEAD}>
              <h2 className={SECTION_TITLE}>
                <Icon name="check_circle" />
                최근 채택 내역
              </h2>
              {data && data.acceptedCount > 0 && (
                <span className="text-xs font-bold text-devin-gray tabular-nums">
                  전체 {formatNumber(data.acceptedCount)}개 중 최근 {data.recentAccepted.length}개
                </span>
              )}
            </div>
            {data && data.recentAccepted.length === 0 && (
              <ListStatus kind="empty">아직 채택된 답변이 없어요.</ListStatus>
            )}
            {data && data.recentAccepted.length > 0 && (
              <ul className="divide-y divide-devin-line">
                {data.recentAccepted.map((item) => (
                  <li key={item.answerId}>
                    <Link
                      className={`flex items-center justify-between gap-4 py-2.5 rounded group ${FOCUS}`}
                      to={detailPath(item.questionId)}
                    >
                      <span className="min-w-0 truncate text-sm font-bold text-devin-ink group-hover:underline">
                        {item.questionTitle}
                      </span>
                      <span className="shrink-0 text-xs text-devin-gray tabular-nums">
                        채택일 {formatDate(item.acceptedAt)}
                      </span>
                    </Link>
                  </li>
                ))}
              </ul>
            )}
          </section>

          {user && <MyActivityList answerCount={data?.answerCount} questionCount={data?.questionCount} />}
        </main>
        <Footer />
      </div>
    </div>
  );
}
